test("25 units of case size 12 ships 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("5 units of case size 12 is raised to 2 cases and 24 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 5, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("24 units of case size 12 is an exact 2 cases and 24 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("exactly one computed case is raised to 2 cases and 24 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 12, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit below one full case is raised to 2 cases and 24 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 11, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("one unit of case size 8 is raised to 2 cases and 16 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 1, caseSize: 8 }), { cases: 2, shippedUnits: 16 });
});

test("29 units of case size 12 rounds up to 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 29, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("31 units of case size 12 rounds up to 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 31, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("30 units of case size 12 is exact halfway and ships 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 30, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("35 units of case size 12 stays at 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 35, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("36 units of case size 12 is an exact 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 36, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("37 units of case size 12 rounds up to 4 cases and 48 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 37, caseSize: 12 }), { cases: 4, shippedUnits: 48 });
});

test("21 units of case size 10 ships 3 cases and 30 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 21, caseSize: 10 }), { cases: 3, shippedUnits: 30 });
});

test("one unit of case size 1 is raised to 2 cases and 2 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 1, caseSize: 1 }), { cases: 2, shippedUnits: 2 });
});

test("13.0 units of case size 6 ships 3 cases and 18 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 13.0, caseSize: 6 }), { cases: 3, shippedUnits: 18 });
});
